package com.yeyamo_mobile.api.referral_service.application;
import java.time.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.referral_service.application.port.FraudCounterPort;import com.yeyamo_mobile.api.referral_service.domain.ReferralException;import com.yeyamo_mobile.api.referral_service.infrastructure.persistence.*;
@Component public class AntiFraudService{
 private final ReferralAttributionRepository attributions;private final FraudCounterPort counter;private final int dailyLimit;private final int deviceLimit;
 public AntiFraudService(ReferralAttributionRepository a,FraudCounterPort c,@Value("${referral.antifraud.max-daily-attributions:20}")int daily,@Value("${referral.antifraud.max-device-attributions:3}")int devices){attributions=a;counter=c;dailyLimit=daily;deviceLimit=devices;}
 public void validate(ReferralCodeEntity code,String referred,String deviceHash){if(code.getOwnerUserId().equals(referred))reject("SELF_REFERRAL","Self-referral is forbidden");if(attributions.findByReferredUserId(referred).isPresent())reject("ALREADY_ATTRIBUTED","User already has a referrer");if(!code.usableAt(Instant.now()))reject("CODE_UNAVAILABLE","Referral code is expired, disabled or exhausted");if(deviceHash!=null&&attributions.countByDeviceHash(deviceHash)>=deviceLimit)reject("DEVICE_LIMIT","Device attribution limit reached");long daily=counter.incrementDaily(code.getOwnerUserId()).orElseGet(()->attributions.countByReferrerUserIdAndAttributedAtAfter(code.getOwnerUserId(),LocalDate.now(ZoneOffset.UTC).atStartOfDay().toInstant(ZoneOffset.UTC))+1);if(daily>dailyLimit)reject("DAILY_LIMIT","Daily referral limit reached");}
 private void reject(String code,String message){throw new ReferralException(code,message);}
}
